---@field BtnQuest                      	UnityEngine.RectTransform                                            
local UIFishPoolHangUpTaskInfoNode = Class("UIFishPoolHangUpTaskInfoNode")
function UIFishPoolHangUpTaskInfoNode:__init() 
    self._queueId = nil
    self._queueDojo = nil
    self._cb = nil
    self._allRewards = {}
    self._timeDown = nil
    self._allBuff = {}
end

function UIFishPoolHangUpTaskInfoNode:__delete()
    self._queueId = nil
    self._queueDojo = nil
    self._cb = nil
    self._allRewards = {}
    self._timeDown = nil
    self._allBuff = {}
end

function UIFishPoolHangUpTaskInfoNode:Awake()    
    SetButtonAction(self.BtnBuff, Bind(self, self.OnBtnBuff))
    self.EventFishHangUpTimeDown = Events.AddListener(Constants.EventNames.FishHangUpTimeDown, Bind(self, self.OnFishHangUpTimeDown))
end

function UIFishPoolHangUpTaskInfoNode:Start()
end

function UIFishPoolHangUpTaskInfoNode:Refresh(queueId, cb)
    if not queueId then
        return
    end
    self._isShow = false
    CfUtils.PlayAnimator(self.Root, "Off")
    KTool.SetActive(self.LoopListBonus, false)

    SetButtonAction(self.FontStyleButtonTask, Bind(self, self.OnBtnDrawReward))

    self._queueId = queueId
    self._queueDojo = fishingComponent:GetHangUpDojoByQueueId(self._queueId)
    if not self._queueDojo then
        return
    end

    self._cb = cb
    self:FillSelf()
end

--初始化buff数据
function UIFishPoolHangUpTaskInfoNode:InitBuffData()
    local t1 = {}
    local dojo = FishingUtils.GetHangUpDojoByQueueId(self._queueId)
    if not dojo then
        return
    end
    if string.isEmpty(checkString(dojo.cards)) then
        return
    end
    
    local t = CfUtils.Split(dojo.cards, ",")
    for k, id in pairs(t) do
        local buffData = FishingUtils.GetActiveCardBuffData(id, Constants.ChooseCardStatus.FishHangeUp) 
        for _, v in pairs(buffData) do
            table.insert(t1, v)
        end
    end
    
    self._allBuff = {}
    local t2 = {}
    for k, v in pairs(t1) do
        if t2[checkString(v.buffData.type)] then
            t2[checkString(v.buffData.type)].value = t2[checkString(v.buffData.type)].value + checkNumber(v.buffData.value)
        else
            t2[checkString(v.buffData.type)] = {
                value = checkNumber(v.buffData.value),
                buffData = v.buffData
            } 
        end
    end
    
    for k, v in pairs(t2) do
        table.insert(self._allBuff, {
            value = v.value,
            buffData = v.buffData
        })
    end
end

function UIFishPoolHangUpTaskInfoNode:OnBtnBuff()
    local isShow = not checkBool(self._isShow)
    self._isShow = isShow

    KTool.SetActive(self.LoopListBonus, isShow)

    if isShow then
        CfUtils.PlayAnimator(self.Root, "On")
        self:RefreshBuffList()
    else
        CfUtils.PlayAnimator(self.Root, "Off")
    end
end

--刷新bufflist
function UIFishPoolHangUpTaskInfoNode:RefreshBuffList()
    self:InitBuffData()
    if self._isInitLoopListBonusList then
        GameUtils.ReloadData(self.LoopListBonus, table.count(self._allBuff))
    else
        self.LoopListBonus:InitListView(table.count(self._allBuff), Bind(self, self.OnRefreshBuffIndex))
        self._isInitLoopListBonusList = true
    end
end

function UIFishPoolHangUpTaskInfoNode:OnRefreshBuffIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("InfoBar")
    local data = self._allBuff[index + 1]

    local Txt1Go = cell.gameObject.transform:Find("Txt1")
    local Txt2Go = cell.gameObject.transform:Find("Txt2")

    local addName = "+"
    local vo = FishingUtils.GetFishingBonusEffectVo(data.buffData.type)
    if vo then
        addName = (checkNumber(vo.isMinus) == 1 and "-" or "+")
    end

    local desc = FishingUtils.GetAdditionDesc(data.buffData) 
    CfUtils.FillText(Txt2Go, addName..checkInt(data.value * 100).."%")
    CfUtils.FillText(Txt1Go, FishingUtils.GetAdditionNoValueDesc(data.buffData, nil, true))

    CfUtils.PlayDelayShowAnimate(cell.gameObject, index)
    return cell
end

function UIFishPoolHangUpTaskInfoNode:FillSelf()
    local placeVo = FishingUtils.GetFishingPlaceVo(self._queueDojo.placeId)
    if placeVo then
        CfUtils.FillText(self.TxtTitle1, placeVo.name)
    end

    self:FillTaskInfo()
    self:FillRewardsInfo()
end

function UIFishPoolHangUpTaskInfoNode:FillTaskInfo()
    local isFinish = FishingUtils.IsHangeUpQueueTaskFinish(self._queueId)
    KTool.SetActive(self.StateTasking, not isFinish)
    KTool.SetActive(self.StateFinish, isFinish)

    --已完成
    if isFinish then
        self.FontStyleButtonTask:ResetFontStyle("B1", localize("领取奖励"))
        self:FillTaskFinishInfo()
    else
        self.FontStyleButtonTask:ResetFontStyle("B5", localize("取消垂钓"))
        self:FillTaskingInfo()
    end
end

--挂机中信息
function UIFishPoolHangUpTaskInfoNode:FillTaskingInfo()
    CfUtils.FillText(self.TxtTimeNumber, CfUtils.GetTimeHMS2(self._queueDojo.remainTime))

    local t = FishingUtils.GetHangUpConsumes(self._queueDojo.placeId)
    table.insert(t, {
        goodsId = Constants.Currency.EnergyId,
        num = FishingUtils.GetFishHangUpEnergyNum(),
    })

    for k, v in pairs(t) do
        local go = self.StateTasking.transform:Find("ImgInform"..k)
        if go then
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(v.goodsId)
            if vo then
                CfUtils.FillImage(go.transform:Find("consumes/icon"), vo.photoPath)
                CfUtils.FillText(go.transform:Find("Txt"), localize("剩余_name_", {_name_ = vo.name}))
            end
            local allNum = v.num * self._queueDojo.totalTimes
            local curFinishNum = FishingUtils.GetCurHangUpFinishNum(self._queueId)
            CfUtils.FillText(go.transform:Find("consumes/num"), ((self._queueDojo.totalTimes - curFinishNum) * v.num).."/"..allNum)
        end
    end
end

--结束
function UIFishPoolHangUpTaskInfoNode:FillTaskFinishInfo()

end

--奖励
function UIFishPoolHangUpTaskInfoNode:FillRewardsInfo()
    self._allRewards = clone(checkTable(self._queueDojo.fish))
    for k, v in pairs(self._queueDojo.rewards) do
        table.insert(self._allRewards, v)
    end

    if not self._isInitList then
        self._isInitList = true
        self.LoopGridReward:InitGridView(table.count(self._allRewards), Bind(self, self.OnRefreshIndex))
    else
        GameUtils.ReloadData(self.LoopGridReward, table.count(self._allRewards))
    end
end

function UIFishPoolHangUpTaskInfoNode:OnRefreshIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    local cell = listView:NewListViewItem("GoodNode")
    local data = self._allRewards[index + 1]
    if data.fishId then
        CfUtils.RefeshGoodGo(cell, data.fishId, data.num, 0.6, nil, function()
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.fishId)
            GameUtils.ShowCommonTipsBoard(cell.gameObject, vo.name, vo.desc.."\n"..vo.description, vo.quality, vo.id, false)
        end, nil, data)
    else
        CfUtils.RefeshGoodGo(cell, data.goodsId, data.num, 0.6, nil, function()
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.goodsId)
            GameUtils.ShowCommonTipsBoard(cell.gameObject, vo.name, vo.desc.."\n"..vo.description, vo.quality, vo.id, false)
        end, nil, data)
    end

    return cell
end

--领取
function UIFishPoolHangUpTaskInfoNode:OnBtnDrawReward()
    fishingComponent:FishingOfflineEndReq(self._queueId)
end

